#!/usr/bin/env python3
import gzip
import json
from itertools import islice

# Config
INFILE = '/workspace/SQuAD.jsonl.gz'
TRAIN_OUT = '/workspace/squad_mini_train.json'
EVAL_OUT = '/workspace/squad_mini_eval.json'
TEST_OUT = '/workspace/squad_mini_test.json'
N_EACH = 10

# Containers
examples = []

with gzip.open(INFILE, 'rt', encoding='utf-8') as f:
    header = json.loads(next(f))
    for line in islice(f, N_EACH):
        ex = json.loads(line)
        context = ex['context']
        for qa in ex['qas']:
            q = qa['question']
            ans = qa['answers']
            aid = qa['id']
            examples.append({
                'id': aid,
                'context': context,
                'question': q,
                'answers': {'text': ans, 'answer_start': []}  # dummy start indices, real pipelines ignore for v1.1
            })

# Create three splits of N_EACH each (repeat if not enough unique questions)
def generate_split(split_name, outfname):
    data = {'data': [
        {
            'title': split_name,
            'paragraphs': [
                {
                    'context': ex['context'],
                    'qas': [
                        {
                            'id': ex['id'],
                            'question': ex['question'],
                            'answers': [{'text': a, 'answer_start': 0} for a in ex['answers']['text']]
                        }
                    ]
                } for ex in examples
            ]
        }
    ]}
    with open(outfname, 'w', encoding='utf-8') as f:
        json.dump(data, f)

# Write out for train/eval/test
for split, fname in zip(["train","eval","test"], [TRAIN_OUT, EVAL_OUT, TEST_OUT]):
    generate_split(split, fname)
print(f"Done. Written: {TRAIN_OUT}, {EVAL_OUT}, {TEST_OUT}")
